import type * as React from 'react';
import type { LucideIcon } from 'lucide-react';

import type { FeaturePackManifestV1, FeaturePackId } from '../../feature-packs';
import type { DatabaseScopedStandaloneConsoleSession } from '../console-runtime';
import type {
  ConsoleKitAdapterContext,
  ConsoleKitAuthMethodConfig,
  ConsoleKitConfig,
  ConsoleKitFeatureAdapter,
  ConsoleKitPasswordPolicy
} from './console-kit-contracts';
import type {
  ConstructiveCallbackCredentialVault,
  ConstructiveConsoleCallback
} from './constructive/constructive-callback';
import type { ConsoleKitRoute } from './console-kit-routes';
import type {
  ConstructiveCapabilityContribution,
  ConstructiveCapabilityDiscovery
} from './constructive/constructive-capabilities';
import type { ConsoleKitStoreApi, ConsoleKitStoreSliceContribution } from './store';

export type ConsoleKitModuleAccountIdentity = Readonly<{
  id: string;
  displayName?: string;
  primaryEmail?: string;
  avatarUrl?: string;
}>;

export type ConsoleKitFeatureComponentProps = Readonly<{
  adapterProps?: unknown;
  config: ConsoleKitConfig;
  runtime: ConsoleKitAdapterContext;
  route: ConsoleKitRoute;
  onRouteChange: (route: ConsoleKitRoute) => void;
  onError: (error: unknown) => void;
}>;

export type ConstructiveFeatureAdapterFactoryContext = Readonly<{
  store: ConsoleKitStoreApi;
  discovery: ConstructiveCapabilityDiscovery;
  session?: DatabaseScopedStandaloneConsoleSession;
  callback?: ConstructiveConsoleCallback;
  callbackCredentials: ConstructiveCallbackCredentialVault;
  authMethods?: ConsoleKitAuthMethodConfig;
  passwordPolicy?: ConsoleKitPasswordPolicy;
}>;

/** One installable feature contribution consumed by the leaf-independent core. */
export type ConsoleKitFeatureModule = Readonly<{
  id: FeaturePackId;
  manifest: FeaturePackManifestV1;
  icon: LucideIcon;
  Component: React.ComponentType<ConsoleKitFeatureComponentProps>;
  createAdapter?: (
    context: ConstructiveFeatureAdapterFactoryContext
  ) => ConsoleKitFeatureAdapter<unknown> | undefined;
  capabilityDiscovery?: ConstructiveCapabilityContribution;
  canRenderWithoutAdapter?: (
    runtime: ConsoleKitAdapterContext
  ) => boolean;
  canRenderWithSessionError?: boolean;
  requiresMetadata?: boolean;
  resolveAccountIdentity?: (
    adapterProps: unknown,
    runtime: ConsoleKitAdapterContext
  ) => ConsoleKitModuleAccountIdentity | undefined;
  storeSlice?: ConsoleKitStoreSliceContribution;
}>;

import type { FeaturePackId } from '../../feature-packs';

export type ConsoleKitAuthRoute =
  | Readonly<{ feature: 'auth'; screen: 'entry' }>
  | Readonly<{ feature: 'auth'; screen: 'recovery' }>
  | Readonly<{ feature: 'auth'; screen: 'callback' }>
  | Readonly<{ feature: 'auth'; screen: 'account' }>
  | Readonly<{ feature: 'auth'; screen: 'security' }>
  | Readonly<{ feature: 'auth'; screen: 'connected-accounts' }>
  | Readonly<{ feature: 'auth'; screen: 'devices' }>
  | Readonly<{ feature: 'auth'; screen: 'sessions' }>;

export type ConsoleKitAppAccessRoute =
  | Readonly<{ feature: 'users'; screen: 'members' }>
  | Readonly<{ feature: 'users'; screen: 'member'; membershipId: string }>
  | Readonly<{ feature: 'users'; screen: 'invitations' }>
  | Readonly<{ feature: 'users'; screen: 'invitation'; invitationId: string }>
  | Readonly<{ feature: 'users'; screen: 'accepted-invites' }>
  | Readonly<{ feature: 'users'; screen: 'profiles' }>
  | Readonly<{ feature: 'users'; screen: 'profile'; profileId: string }>
  | Readonly<{ feature: 'users'; screen: 'capabilities' }>
  | Readonly<{ feature: 'users'; screen: 'defaults' }>;

type OrganizationRouteBase = Readonly<{
  feature: 'organizations';
  organizationId: string;
}>;

export type ConsoleKitOrganizationsRoute =
  | Readonly<{ feature: 'organizations'; screen: 'organizations' }>
  | Readonly<{ feature: 'organizations'; screen: 'create' }>
  | (OrganizationRouteBase & Readonly<{
      screen:
        | 'overview'
        | 'settings'
        | 'members'
        | 'invitations'
        | 'profiles'
        | 'capabilities'
        | 'defaults'
        | 'hierarchy'
        | 'developer'
        | 'api-keys'
        | 'principals';
    }>)
  | (OrganizationRouteBase & Readonly<{
      screen: 'member';
      membershipId: string;
    }>)
  | (OrganizationRouteBase & Readonly<{
      screen: 'invitation';
      invitationId: string;
    }>)
  | (OrganizationRouteBase & Readonly<{
      screen: 'profile';
      profileId: string;
    }>);

export type ConsoleKitDataRoute =
  | Readonly<{ feature: 'data'; screen: 'tables' }>
  | Readonly<{ feature: 'data'; screen: 'table'; tableId: string }>;

export type ConsoleKitStorageRoute =
  | Readonly<{ feature: 'storage'; screen: 'buckets' }>
  | Readonly<{
      feature: 'storage';
      screen: 'bucket';
      bucketId: string;
      path?: string;
    }>;

export type ConsoleKitBillingRoute =
  | Readonly<{ feature: 'billing'; screen: 'overview' }>
  | Readonly<{ feature: 'billing'; screen: 'usage' }>
  | Readonly<{ feature: 'billing'; screen: 'settings' }>;

export type ConsoleKitNotificationsRoute =
  | Readonly<{ feature: 'notifications'; screen: 'inbox' }>
  | Readonly<{
      feature: 'notifications';
      screen: 'message';
      notificationId: string;
    }>;

/**
 * Every Console Kit location is a semantic route. Detail identifiers only
 * exist on detail variants, so consumers do not have to interpret optional
 * route bags or rebuild feature-specific path parsing.
 */
export type ConsoleKitRoute =
  | ConsoleKitAuthRoute
  | ConsoleKitAppAccessRoute
  | ConsoleKitOrganizationsRoute
  | ConsoleKitDataRoute
  | ConsoleKitStorageRoute
  | ConsoleKitBillingRoute
  | ConsoleKitNotificationsRoute;

export function defaultConsoleKitRoute(
  feature: FeaturePackId
): ConsoleKitRoute {
  switch (feature) {
    case 'auth':
      return { feature, screen: 'entry' };
    case 'users':
      return { feature, screen: 'members' };
    case 'organizations':
      return { feature, screen: 'organizations' };
    case 'storage':
      return { feature, screen: 'buckets' };
    case 'billing':
      return { feature, screen: 'overview' };
    case 'notifications':
      return { feature, screen: 'inbox' };
    case 'data':
      return { feature, screen: 'tables' };
  }
}

export function consoleKitRouteKey(route: ConsoleKitRoute): string {
  switch (route.screen) {
    case 'member':
      return 'organizationId' in route
        ? `${route.feature}:${route.screen}:${route.organizationId}:${route.membershipId}`
        : `${route.feature}:${route.screen}:${route.membershipId}`;
    case 'invitation':
      return 'organizationId' in route
        ? `${route.feature}:${route.screen}:${route.organizationId}:${route.invitationId}`
        : `${route.feature}:${route.screen}:${route.invitationId}`;
    case 'profile':
      return 'organizationId' in route
        ? `${route.feature}:${route.screen}:${route.organizationId}:${route.profileId}`
        : `${route.feature}:${route.screen}:${route.profileId}`;
    case 'table':
      return `${route.feature}:${route.screen}:${route.tableId}`;
    case 'bucket':
      return `${route.feature}:${route.screen}:${route.bucketId}:${route.path ?? ''}`;
    case 'message':
      return `${route.feature}:${route.screen}:${route.notificationId}`;
    default:
      return 'organizationId' in route
        ? `${route.feature}:${route.screen}:${route.organizationId}`
        : `${route.feature}:${route.screen}`;
  }
}

import type { QueryClient } from '@tanstack/react-query';
import type {
  IntrospectionQueryResponse,
  MetaContractIntrospectionQuery,
  MetaQuery
} from '@constructive-io/data';
import type {
  WorkspaceAccount,
  WorkspaceBrand
} from '@/components/ui/workspace-kit/shell';
import type { NavRowLinkProps } from '@/components/ui/workspace-kit/nav';

import type {
  ConsoleEndpoint,
  ConsoleEndpointInput,
  ConsoleEndpointKind,
  ConsoleEndpointMap,
  ConsoleRuntimeError,
  ConsoleSession,
  ConsoleSessionSnapshot,
  ConsoleTransport,
  IdentityScopedConsoleTransport,
  FeatureAdapter,
  FeatureAvailability
} from '../console-runtime';
import type { AtomicCapabilityId, FeaturePackId } from '../../feature-packs';
import type { ConsoleKitFeatureModule } from './feature-module';
import type { ConsoleKitRoute } from './console-kit-routes';
import type { ConsoleKitStoreApi } from './store';

export type ConsoleKitMetadataState =
  | Readonly<{ status: 'checking' }>
  | Readonly<{
      status: 'compatible';
      meta: MetaQuery;
      contractIntrospection: MetaContractIntrospectionQuery;
      introspection: IntrospectionQueryResponse;
    }>
  | Readonly<{
      status: 'incompatible';
      message: string;
      missing: readonly string[];
    }>
  | Readonly<{ status: 'error'; error: ConsoleRuntimeError }>;

export type ConsoleKitFeatureAvailability = FeatureAvailability;

export type ConsoleKitAdapterContext = Readonly<{
  databaseId: string;
  endpoints: Readonly<Partial<Record<ConsoleEndpointKind, ConsoleEndpoint>>>;
  /** Session ownership determines whether a pack can expose standalone flows. */
  sessionMode?: ConsoleSession['mode'];
  session: ConsoleSessionSnapshot;
  metadata: ConsoleKitMetadataState;
  metadataByEndpoint?: Readonly<
    Partial<Record<ConsoleEndpointKind, ConsoleKitMetadataState>>
  >;
  transportFor: (kind: ConsoleEndpointKind) => IdentityScopedConsoleTransport | null;
}>;

export type ConsoleKitFeatureAdapter<TProps> = FeatureAdapter<
  TProps,
  ConsoleKitAdapterContext,
  AtomicCapabilityId
> & Readonly<{
  /** First-party adapters wait for live schema/capability discovery before loading. */
  requiresCapabilityDiscovery?: boolean;
}>;

export type ConsoleKitFeaturePropsMap = Readonly<
  Record<FeaturePackId, unknown>
>;

export type ConsoleKitAdapters = Readonly<
  Partial<Record<FeaturePackId, ConsoleKitFeatureAdapter<unknown>>>
>;

export type ConsoleKitAdapterEnhancer = (
  adapter: ConsoleKitFeatureAdapter<unknown> | undefined
) => ConsoleKitFeatureAdapter<unknown> | undefined;

export type ConsoleKitAdapterEnhancers = Readonly<
  Partial<Record<FeaturePackId, ConsoleKitAdapterEnhancer>>
>;

export type ConsoleKitAuthMethod =
  | 'password'
  | 'email-otp'
  | 'sms-otp'
  | 'totp'
  | 'passkey'
  | 'oauth';

export type ConsoleKitPasswordPolicy = Readonly<{
  minLength?: number;
  maxLength?: number;
  hint?: string;
  validate?: (password: string) => string | undefined;
}>;

/**
 * Undefined methods are discovered from complete public operation chains.
 * False always hides a method; true permits it only when a trusted adapter can
 * prove and own the complete start-to-finish flow.
 */
export type ConsoleKitAuthMethodConfig = Readonly<
  Partial<Record<ConsoleKitAuthMethod, boolean>>
>;

export type ConsoleKitEndpointResolver = (input: Readonly<{
  databaseId: string;
  kind: ConsoleEndpointKind;
}>) => ConsoleEndpointInput | undefined;

export type ConsoleKitRouteConfig = Readonly<{
  /** When supplied, the host owns navigation state. */
  route?: ConsoleKitRoute;
  defaultRoute?: ConsoleKitRoute;
  getHref?: (route: ConsoleKitRoute) => string;
  onRouteChange?: (route: ConsoleKitRoute) => void;
  renderLink?: (props: NavRowLinkProps) => React.ReactElement;
}>;

export type ConsoleKitConfig = Readonly<{
  databaseId: string;
  endpoints?: ConsoleEndpointMap;
  resolveEndpoint?: ConsoleKitEndpointResolver;
  session: ConsoleSession;
  transport?: ConsoleTransport;
  adapters?: ConsoleKitAdapters;
  adapterEnhancers?: ConsoleKitAdapterEnhancers;
  authMethods?: ConsoleKitAuthMethodConfig;
  authPasswordPolicy?: ConsoleKitPasswordPolicy;
  queryClient?: QueryClient;
  order?: readonly FeaturePackId[];
  labels?: Partial<Record<FeaturePackId, string>>;
  showUnavailable?: boolean;
  /**
   * When true, expose connection/endpoint/_meta diagnostics in the shell.
   * Default false — those belong in host config and degraded-state details.
   */
  showDiagnostics?: boolean;
  routes?: ConsoleKitRouteConfig;
  /** Pack-owned configuration keyed by an installed feature module id. */
  featureOptions?: Readonly<Partial<Record<FeaturePackId, unknown>>>;
  brand?: WorkspaceBrand;
  account?: WorkspaceAccount;
  onError?: (
    error: ConsoleRuntimeError,
    context: Readonly<{
      phase: 'metadata' | 'adapter' | 'feature';
      feature?: FeaturePackId;
    }>
  ) => void;
  renderUnavailableFeature?: (
    feature: FeaturePackId,
    availability: ConsoleKitFeatureAvailability
  ) => React.ReactNode;
}>;

export type ConsoleKitProps = Readonly<{
  config: ConsoleKitConfig;
  /** The exact feature modules installed into this console instance. */
  featureModules: readonly ConsoleKitFeatureModule[];
  className?: string;
  /** Optional pre-created per-console store for host integration and testing. */
  store?: ConsoleKitStoreApi;
}>;

'use client';

import * as React from 'react';
import { CheckIcon, CopyIcon, DatabaseIcon } from 'lucide-react';

import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Popover,
  PopoverContent,
  PopoverDescription,
  PopoverTitle,
  PopoverTrigger
} from '@/components/ui/popover';

import {
  CONSOLE_ENDPOINT_KINDS,
  type ConsoleEndpoint,
  type ConsoleEndpointKind
} from '../console-runtime';
import type { ConsoleKitMetadataState } from './console-kit-contracts';
import { cn } from '@/lib/utils';

type ConsoleConnectionMenuProps = Readonly<{
  databaseId: string;
  databaseLabel?: React.ReactNode;
  endpoints: Readonly<Partial<Record<ConsoleEndpointKind, ConsoleEndpoint>>>;
  metadataStatus?: ConsoleKitMetadataState['status'];
}>;

type CopyFeedback = Readonly<{
  target: string;
  message: string;
  status: 'copied' | 'error';
}>;

function endpointLabel(kind: ConsoleEndpointKind): string {
  return kind.charAt(0).toUpperCase() + kind.slice(1);
}

function metadataBadge(status: ConsoleKitMetadataState['status'] | undefined) {
  if (status === 'compatible') {
    return { label: '_meta ready', variant: 'outline' as const };
  }
  if (!status) {
    return { label: '_meta not checked', variant: 'secondary' as const };
  }
  if (status === 'checking') {
    return { label: 'Checking _meta', variant: 'secondary' as const };
  }
  if (status === 'incompatible') {
    return { label: 'Incompatible _meta', variant: 'destructive' as const };
  }
  return { label: 'Metadata issue', variant: 'destructive' as const };
}

export function ConsoleConnectionMenu({
  databaseId,
  databaseLabel,
  endpoints,
  metadataStatus
}: ConsoleConnectionMenuProps) {
  const [feedback, setFeedback] = React.useState<CopyFeedback | null>(null);
  const resolvedEndpoints = CONSOLE_ENDPOINT_KINDS.flatMap((kind) => {
    const endpoint = endpoints[kind];
    return endpoint ? [{ endpoint, kind }] : [];
  });
  const meta = metadataBadge(metadataStatus);
  const triggerLabel = metadataStatus === 'compatible' || !metadataStatus
    ? 'Connection'
    : metadataStatus === 'checking'
      ? 'Checking…'
      : 'Connection issue';

  const copy = async (target: string, label: string, value: string) => {
    try {
      if (!navigator.clipboard?.writeText) {
        throw new Error('Clipboard access is unavailable.');
      }
      await navigator.clipboard.writeText(value);
      setFeedback({
        target,
        message: `${label} copied.`,
        status: 'copied'
      });
    } catch {
      setFeedback({
        target,
        message: `${label} could not be copied.`,
        status: 'error'
      });
    }
  };

  return (
    <Popover onOpenChange={(open) => {
      if (!open) setFeedback(null);
    }}>
      <PopoverTrigger
        render={
          <Button
            aria-label={`${triggerLabel}. Open connection details.`}
            className='max-w-[11rem] sm:max-w-none'
            size='sm'
            variant='outline'
          />
        }
      >
        <DatabaseIcon aria-hidden='true' data-icon='inline-start' />
        <span className='truncate'>{triggerLabel}</span>
        <Badge
          className='hidden max-w-24 truncate sm:inline-flex'
          size='sm'
          variant={meta.variant}
        >
          {meta.label}
        </Badge>
      </PopoverTrigger>
      <PopoverContent align='end' className='w-[calc(100vw-1rem)] max-w-96 rounded-xl sm:w-96'>
        <div className='flex items-start justify-between gap-3'>
          <div className='min-w-0'>
            <PopoverTitle className='text-balance'>Database connection</PopoverTitle>
            <PopoverDescription className='mt-1 text-pretty'>
              Resolved tenant identity, metadata status, and GraphQL routes for this console.
            </PopoverDescription>
          </div>
          <Badge className='shrink-0' size='sm' variant={meta.variant}>
            {meta.label}
          </Badge>
        </div>

        <div className='mt-4 grid gap-4'>
          <div className='grid gap-2'>
            <p className='text-muted-foreground text-xs font-medium'>Database</p>
            {databaseLabel ? (
              <div
                className='min-w-0 truncate text-sm font-medium'
                title={typeof databaseLabel === 'string' ? databaseLabel : undefined}
              >
                {databaseLabel}
              </div>
            ) : null}
            <div className='bg-muted/60 flex min-w-0 items-center gap-2 rounded-md px-2 py-1.5 ring-1 ring-border/60'>
              <code className='min-w-0 flex-1 truncate text-xs' title={databaseId}>
                {databaseId}
              </code>
              <Button
                aria-label='Copy database ID'
                onClick={() => void copy('database', 'Database ID', databaseId)}
                size='icon-sm'
                type='button'
                variant='ghost'
              >
                {feedback?.target === 'database' && feedback.status === 'copied'
                  ? <CheckIcon aria-hidden='true' />
                  : <CopyIcon aria-hidden='true' />}
              </Button>
            </div>
          </div>

          <div className='grid gap-2'>
            <div className='flex items-center justify-between gap-3'>
              <p className='text-muted-foreground text-xs font-medium'>Endpoints</p>
              <span className='text-muted-foreground text-xs tabular-nums'>
                {resolvedEndpoints.length} routed
              </span>
            </div>
            {resolvedEndpoints.length > 0 ? (
              <div className='scrollbar-neutral-thin grid max-h-72 gap-2 overflow-y-auto pr-0.5'>
                {resolvedEndpoints.map(({ endpoint, kind }) => {
                  const target = `endpoint-${kind}`;
                  const label = `${endpointLabel(kind)} endpoint URL`;
                  return (
                    <div
                      className='bg-muted/60 flex min-w-0 items-center gap-2 rounded-md px-2 py-1.5 ring-1 ring-border/60'
                      key={kind}
                    >
                      <Badge className='shrink-0' size='sm' variant='outline'>
                        {endpointLabel(kind)}
                      </Badge>
                      <code className='min-w-0 flex-1 truncate text-xs' title={endpoint.url}>
                        {endpoint.url}
                      </code>
                      <Button
                        aria-label={`Copy ${label.toLowerCase()}`}
                        onClick={() => void copy(target, label, endpoint.url)}
                        size='icon-sm'
                        type='button'
                        variant='ghost'
                      >
                        {feedback?.target === target && feedback.status === 'copied'
                          ? <CheckIcon aria-hidden='true' />
                          : <CopyIcon aria-hidden='true' />}
                      </Button>
                    </div>
                  );
                })}
              </div>
            ) : (
              <p className='text-muted-foreground text-pretty text-sm'>
                No endpoint URLs are resolved. Configure at least the data route to connect this console.
              </p>
            )}
          </div>

          <p
            aria-live='polite'
            className={cn(
              'text-muted-foreground min-h-4 text-pretty text-xs',
              feedback?.status === 'error' && 'text-destructive'
            )}
            role={feedback?.status === 'error' ? 'alert' : 'status'}
          >
            {feedback?.message}
          </p>
        </div>
      </PopoverContent>
    </Popover>
  );
}

'use client';

import * as React from 'react';
import {
  ChevronRightIcon,
  ChevronsUpDownIcon,
  CircleDashedIcon,
  DatabaseIcon,
  LockKeyholeIcon,
  TriangleAlertIcon
} from 'lucide-react';

import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger
} from '@/components/ui/dropdown-menu';
import { NavRow, NavSection, SidebarFrame, type NavRowLinkProps } from '@/components/ui/workspace-kit/nav';
import { focusRingClass, NavMenuButton } from '@/components/ui/workspace-kit/primitives';
import {
  WorkspaceShell,
  type WorkspaceAccount,
  type WorkspaceBrand,
  type WorkspaceNavigationGroup,
  type WorkspaceNavigationItem,
  type WorkspaceSidebarRenderProps
} from '@/components/ui/workspace-kit/shell';
import { cn } from '@/lib/utils';

/** Why a feature row isn't simply open: shown as a quiet glyph, announced through the row's badge text. */
export type ConsoleNavigationStatus = 'checking' | 'locked' | 'partial' | 'setup';

export type ConsoleNavigationItem = WorkspaceNavigationItem & Readonly<{ status?: ConsoleNavigationStatus }>;

export type ConsoleNavigationGroup = Omit<WorkspaceNavigationGroup, 'items'> & Readonly<{
  items: readonly ConsoleNavigationItem[];
}>;

export type ConsoleBreadcrumb = Readonly<{ id: string; label: React.ReactNode; current?: boolean }>;

export type ConsoleShellProps = Readonly<{
  navigation: readonly ConsoleNavigationGroup[];
  brand: WorkspaceBrand;
  account?: WorkspaceAccount;
  breadcrumbs?: readonly ConsoleBreadcrumb[];
  renderLink?: (props: NavRowLinkProps) => React.ReactElement;
  /** Right side of the top bar, e.g. the connection menu. */
  barActions?: React.ReactNode;
  className?: string;
  children: React.ReactNode;
}>;

const STATUS_GLYPH: Readonly<Record<Exclude<ConsoleNavigationStatus, 'checking'>, typeof LockKeyholeIcon>> = {
  locked: LockKeyholeIcon,
  partial: CircleDashedIcon,
  setup: TriangleAlertIcon
};

function initials(name: string) {
  return name.split(/\s+/u).filter(Boolean).slice(0, 2).map((part) => part[0]?.toUpperCase()).join('');
}

function BrandMark({ brand, collapsed }: Readonly<{ brand: WorkspaceBrand; collapsed: boolean }>) {
  const name = typeof brand.name === 'string' ? brand.name : 'Application';
  const content = (
    <>
      <span aria-hidden='true' className='bg-foreground text-background grid size-5 shrink-0 place-items-center rounded-md [&_svg]:size-3'>
        {brand.logo ?? <DatabaseIcon />}
      </span>
      {collapsed ? <span className='sr-only'>{name}</span> : (
        <span className='min-w-0 flex-1'>
          <span className='text-foreground block truncate text-sm font-medium'>{brand.name}</span>
        </span>
      )}
    </>
  );
  const className = cn('flex h-8 min-w-0 items-center gap-2 rounded-md px-1.5', collapsed ? 'w-8 justify-center px-0' : 'flex-1');
  return brand.href
    ? <a className={cn(className, 'hover:bg-overlay-hover', focusRingClass)} href={brand.href}>{content}</a>
    : <div className={className}>{content}</div>;
}

/** The signed-in person at the foot of the sidebar, opening their session actions. */
function AccountMenu({
  account,
  collapsed,
  renderLink
}: Readonly<{ account: WorkspaceAccount; collapsed: boolean; renderLink?: ConsoleShellProps['renderLink'] }>) {
  const avatar = (
    <Avatar className='size-6 shrink-0 ring-1 ring-foreground/[0.06]'>
      {account.avatarUrl ? <AvatarImage alt={account.avatarAlt ?? ''} src={account.avatarUrl} /> : null}
      <AvatarFallback className='bg-muted text-[10px] font-medium'>{account.fallback ?? initials(account.name)}</AvatarFallback>
    </Avatar>
  );
  const groups = account.actionGroups?.filter((group) => group.actions.length > 0) ?? [];
  const person = (
    <span className='min-w-0 flex-1 text-left'>
      <span className='text-foreground block truncate text-[13px] font-medium'>{account.name}</span>
      {account.secondaryLabel ? <span className='text-muted-foreground block truncate text-xs'>{account.secondaryLabel}</span> : null}
    </span>
  );

  if (groups.length === 0) {
    return (
      <div className={cn('flex items-center gap-2 border-t border-sidebar-border p-2.5', collapsed && 'justify-center')} data-slot='console-account'>
        {avatar}
        {collapsed ? <span className='sr-only'>{account.name}</span> : person}
      </div>
    );
  }

  return (
    <div className='border-t border-sidebar-border p-2' data-slot='console-account'>
      <DropdownMenu>
        <DropdownMenuTrigger
          aria-label={`Account: ${account.name}`}
          className={cn(
            'hover:bg-overlay-hover data-[popup-open]:bg-overlay-hover flex w-full cursor-pointer items-center gap-2 rounded-md p-1.5',
            collapsed && 'justify-center',
            focusRingClass
          )}
        >
          {avatar}
          {collapsed ? null : (
            <>
              {person}
              <ChevronsUpDownIcon aria-hidden='true' className='text-muted-foreground size-3.5 shrink-0' />
            </>
          )}
        </DropdownMenuTrigger>
        <DropdownMenuContent align='start' className='w-60' side={collapsed ? 'right' : 'top'}>
          <DropdownMenuLabel className='flex items-center gap-2.5 py-2 font-normal'>
            {avatar}
            {person}
          </DropdownMenuLabel>
          {groups.map((group) => (
            <React.Fragment key={group.id}>
              <DropdownMenuSeparator />
              <DropdownMenuGroup>
                {group.label ? <DropdownMenuLabel className='text-muted-foreground text-xs font-normal'>{group.label}</DropdownMenuLabel> : null}
                {group.actions.map((action) => {
                  const Icon = action.icon;
                  const body = (
                    <>
                      {Icon ? <Icon aria-hidden='true' className='size-3.5' /> : null}
                      {action.label}
                    </>
                  );
                  return action.href ? (
                    <DropdownMenuItem
                      className='gap-2'
                      disabled={action.disabled}
                      key={action.id}
                      render={renderLink ? renderLink({ href: action.href }) : <a href={action.href} />}
                      variant={action.variant}
                    >
                      {body}
                    </DropdownMenuItem>
                  ) : (
                    <DropdownMenuItem
                      className='gap-2'
                      disabled={action.disabled}
                      key={action.id}
                      onClick={action.onSelect}
                      variant={action.variant}
                    >
                      {body}
                    </DropdownMenuItem>
                  );
                })}
              </DropdownMenuGroup>
            </React.Fragment>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

function ItemIcon({ icon: Icon, active }: Readonly<{ icon?: WorkspaceNavigationItem['icon']; active?: boolean }>) {
  if (!Icon) return <span aria-hidden='true' className='size-3.5 shrink-0' />;
  return <Icon aria-hidden='true' className={cn('size-3.5 shrink-0', active ? 'text-foreground' : 'text-muted-foreground')} />;
}

function StatusGlyph({ status, badge }: Readonly<{ status?: ConsoleNavigationStatus; badge?: React.ReactNode }>) {
  if (!status || status === 'checking') {
    return badge ? <span className='text-muted-foreground text-xs'>{badge}</span> : null;
  }
  const Glyph = STATUS_GLYPH[status];
  return (
    <span className={cn('flex shrink-0 items-center', status === 'setup' ? 'text-warning' : 'text-muted-foreground')}>
      <Glyph aria-hidden='true' className='size-3.5' />
      {badge ? <span className='sr-only'>{badge}</span> : null}
    </span>
  );
}

/**
 * Console Kit's frame on the shared workspace shell: the application's
 * features in the sidebar (links, so hosts keep their router), the signed-in
 * account at its foot, and a slim bar with the current location and any host
 * actions. Below the sidebar breakpoint the features move into the drawer.
 */
export function ConsoleShell({
  navigation,
  brand,
  account,
  breadcrumbs,
  renderLink,
  barActions,
  className,
  children
}: ConsoleShellProps) {
  const sidebar = ({ mode, collapsed, onCollapsedChange, onNavigate }: WorkspaceSidebarRenderProps) => {
    const railCollapsed = mode === 'rail' && collapsed;
    return (
      <SidebarFrame
        collapsed={collapsed}
        drawer={mode === 'drawer'}
        footer={account ? <AccountMenu account={account} collapsed={railCollapsed} renderLink={renderLink} /> : null}
        label='Application'
        menu={<BrandMark brand={brand} collapsed={railCollapsed} />}
        onClose={onNavigate}
        onCollapsedChange={onCollapsedChange}
      >
        {navigation.map((group) => (
          <NavSection collapsed={railCollapsed} key={group.id} title={typeof group.label === 'string' ? group.label : undefined}>
            {group.items.map((item) => {
              const label = typeof item.label === 'string' ? item.label : item.id;
              return (
                <NavRow
                  active={item.isActive}
                  busy={item.status === 'checking'}
                  collapsed={railCollapsed}
                  disabled={item.disabled}
                  href={item.href ?? `#${item.id}`}
                  key={item.id}
                  label={label}
                  leading={<ItemIcon active={item.isActive} icon={item.icon} />}
                  muted={Boolean(item.status && item.status !== 'checking')}
                  onClick={onNavigate}
                  renderLink={renderLink}
                  trailing={<StatusGlyph badge={item.badge} status={item.status} />}
                />
              );
            })}
          </NavSection>
        ))}
      </SidebarFrame>
    );
  };

  return (
    <WorkspaceShell className={cn('h-dvh', className)} sidebar={sidebar} slot='console-kit'>
      <div className='flex min-w-0 flex-1 flex-col'>
        <header className='flex h-12 shrink-0 items-center gap-2 border-b border-dashed border-foreground/10 px-4'>
          <NavMenuButton />
          {breadcrumbs?.length ? (
            <nav aria-label='Breadcrumb' className='min-w-0 flex-1'>
              <ol className='flex min-w-0 items-center gap-1 text-sm'>
                {breadcrumbs.map((crumb, index) => (
                  <li className='flex min-w-0 items-center gap-1' key={crumb.id}>
                    {index > 0 ? <ChevronRightIcon aria-hidden='true' className='text-subtle-foreground size-3.5 shrink-0' /> : null}
                    <span
                      aria-current={crumb.current ? 'page' : undefined}
                      className={cn('truncate', crumb.current ? 'text-foreground font-medium' : 'text-muted-foreground')}
                    >
                      {crumb.label}
                    </span>
                  </li>
                ))}
              </ol>
            </nav>
          ) : <div className='flex-1' />}
          {barActions ? <div className='flex shrink-0 items-center gap-1.5'>{barActions}</div> : null}
        </header>
        <div className='min-h-0 flex-1 overflow-y-auto outline-none' id='main-content' tabIndex={-1}>
          <div className='mx-auto flex min-h-full w-full max-w-6xl min-w-0 flex-col gap-4 p-4 sm:p-6 lg:p-8'>
            {children}
          </div>
        </div>
      </div>
    </WorkspaceShell>
  );
}

