type ParsedSource = Readonly<{
  params: URLSearchParams;
  query: URLSearchParams;
  fragment: URLSearchParams | null;
  url: URL | null;
}>;

type UniqueValue =
  | Readonly<{ status: 'missing' }>
  | Readonly<{ status: 'ready'; value: string }>
  | Readonly<{ status: 'conflict' }>;

function parameterFragment(hash: string): URLSearchParams | null {
  const value = hash.replace(/^#\??/u, '');
  return value.includes('=') ? new URLSearchParams(value) : null;
}

function parseSource(source: ConstructiveConsoleCallbackSource): ParsedSource {
  if (source instanceof URLSearchParams) {
    const query = new URLSearchParams(source);
    return { params: new URLSearchParams(query), query, fragment: null, url: null };
  }

  const url = source instanceof URL
    ? new URL(source.href)
    : new URL(source, 'https://constructive.invalid');
  const query = new URLSearchParams(url.search);
  const fragment = parameterFragment(url.hash);
  const params = new URLSearchParams(query);
  fragment?.forEach((value, key) => params.append(key, value));
  return { params, query, fragment, url };
}

function uniqueValue(
  params: URLSearchParams,
  keys: readonly string[]
): UniqueValue {
  const values = new Set(
    keys.flatMap((key) => params.getAll(key))
      .map((value) => value.trim())
      .filter(Boolean)
  );
  if (values.size === 0) return { status: 'missing' };
  if (values.size > 1) return { status: 'conflict' };
  return { status: 'ready', value: [...values][0] as string };
}

function normalizeKind(value: string): ConstructiveConsoleCallbackKind | null {
  switch (value.trim().toLowerCase().replaceAll('_', '-')) {
    case 'forgot-password':
    case 'password-reset':
    case 'reset-password':
      return 'password-reset';
    case 'email-verification':
    case 'verify-email':
      return 'email-verification';
    case 'account-deletion':
    case 'delete-account':
      return 'account-deletion';
    case 'app':
    case 'app-invite':
      return 'app-invite';
    case 'org':
    case 'org-invite':
    case 'organization-invite':
      return 'organization-invite';
    default:
      return null;
  }
}

function inferKind(parsed: ParsedSource): UniqueValue & {
  kind?: ConstructiveConsoleCallbackKind;
} {
  const explicit = uniqueValue(parsed.params, CALLBACK_TYPE_KEYS);
  if (explicit.status === 'conflict') return explicit;
  if (explicit.status === 'ready') {
    const kind = normalizeKind(explicit.value);
    return kind ? { status: 'ready', value: explicit.value, kind } : explicit;
  }

  const inviteType = uniqueValue(parsed.params, ['type']);
  if (inviteType.status === 'conflict') return inviteType;
  const inviteKind = inviteType.status === 'ready'
    ? normalizeKind(inviteType.value)
    : null;
  if (
    inviteType.status === 'ready' &&
    (inviteKind === 'app-invite' || inviteKind === 'organization-invite')
  ) {
    return { status: 'ready', value: inviteType.value, kind: inviteKind };
  }

  const pathname = parsed.url?.pathname.toLowerCase() ?? '';
  const pathKind = [
    'password-reset',
    'email-verification',
    'account-deletion',
    'app-invite',
    'organization-invite'
  ].find((candidate) => CALLBACK_PATH_ALIASES[
    candidate as ConstructiveConsoleCallbackKind
  ].some((alias) => pathname.includes(alias))) as
    ConstructiveConsoleCallbackKind | undefined;
  if (pathKind) return { status: 'ready', value: pathKind, kind: pathKind };

  if (uniqueValue(parsed.params, DELETION_TOKEN_KEYS).status === 'ready' &&
      uniqueValue(parsed.params, ['account_deletion_token', 'accountDeletionToken']).status === 'ready') {
    return { status: 'ready', value: 'account-deletion', kind: 'account-deletion' };
  }
  if (uniqueValue(parsed.params, ['verification_token', 'verificationToken']).status === 'ready') {
    return { status: 'ready', value: 'email-verification', kind: 'email-verification' };
  }
  if (uniqueValue(parsed.params, ['reset_token', 'resetToken']).status === 'ready') {
    return { status: 'ready', value: 'password-reset', kind: 'password-reset' };
  }
  if (uniqueValue(parsed.params, ['invite_token', 'inviteToken']).status === 'ready') {
    return { status: 'conflict' };
  }
  return { status: 'missing' };
}

function scrubbedUrl(parsed: ParsedSource): string | undefined {
  if (!parsed.url) return undefined;
  for (const key of CALLBACK_PARAMETER_KEYS) {
    parsed.query.delete(key);
    parsed.fragment?.delete(key);
  }
  parsed.url.search = parsed.query.toString();
  if (parsed.fragment) {
    const fragment = parsed.fragment.toString();
    parsed.url.hash = fragment ? `#${fragment}` : '';
  }
  return `${parsed.url.pathname}${parsed.url.search}${parsed.url.hash}`;
}

function callbackSignalPresent(params: URLSearchParams): boolean {
  return [
    ...CALLBACK_TYPE_KEYS,
    'reset_token',
    'resetToken',
    'verification_token',
    'verificationToken',
    'account_deletion_token',
    'accountDeletionToken',
    'invite_token',
    'inviteToken'
  ].some((key) => params.has(key)) ||
    ['app', 'org', 'app-invite', 'org-invite', 'organization-invite']
      .includes(params.get('type') ?? '');
}

/**
 * Parses both query and fragment callback forms, binds legacy tenant-domain
 * links to the expected database, rejects an explicit cross-tenant database,
 * and returns only an opaque reference to the captured credential.
 */
export function parseConstructiveConsoleCallback(
  source: ConstructiveConsoleCallbackSource,
  options: Readonly<{
    databaseId: string;
    credentialVault: ConstructiveCallbackCredentialVault;
  }>
): ConstructiveConsoleCallbackResult {
  let parsed: ParsedSource;
  try {
    parsed = parseSource(source);
  } catch {
    return { status: 'invalid', message: 'The callback URL is malformed.' };
  }

  const inferred = inferKind(parsed);
  if (inferred.status === 'missing' && !callbackSignalPresent(parsed.params)) {
    return { status: 'none' };
  }
  const sanitizedUrl = scrubbedUrl(parsed);
  if (inferred.status === 'missing') {
    return {
      status: 'invalid',
      message: 'The callback type is missing or unsupported.',
      sanitizedUrl
    };
  }
  if (inferred.status === 'conflict' || !inferred.kind) {
    return {
      status: 'invalid',
      message: 'The callback contains conflicting or unsupported fields.',
      sanitizedUrl
    };
  }
  const kind = inferred.kind;

  const database = uniqueValue(parsed.params, DATABASE_ID_KEYS);
  if (database.status === 'conflict') {
    return {
      status: 'invalid',
      message: 'The callback contains conflicting tenant database identifiers.',
      sanitizedUrl
    };
  }
  const callbackDatabaseId = database.status === 'ready'
    ? database.value
    : options.databaseId;
  if (callbackDatabaseId !== options.databaseId) {
    return {
      status: 'cross-tenant',
      kind,
      expectedDatabaseId: options.databaseId,
      callbackDatabaseId,
      message: 'This callback belongs to a different tenant database.',
      sanitizedUrl
    };
  }

  const fields = (() => {
    switch (kind) {
      case 'password-reset':
        return {
          identity: uniqueValue(parsed.params, ROLE_ID_KEYS),
          credential: uniqueValue(parsed.params, RESET_TOKEN_KEYS),
          identityLabel: 'role_id'
        };
      case 'email-verification':
        return {
          identity: uniqueValue(parsed.params, EMAIL_ID_KEYS),
          credential: uniqueValue(parsed.params, VERIFICATION_TOKEN_KEYS),
          identityLabel: 'email_id'
        };
      case 'account-deletion':
        return {
          identity: uniqueValue(parsed.params, USER_ID_KEYS),
          credential: uniqueValue(parsed.params, DELETION_TOKEN_KEYS),
          identityLabel: 'user_id'
        };
      case 'app-invite':
      case 'organization-invite':
        return {
          identity: null,
          credential: uniqueValue(parsed.params, INVITE_TOKEN_KEYS),
          identityLabel: null
        };
    }
  })();
  if (fields.identity?.status === 'conflict' || fields.credential.status === 'conflict') {
    return {
      status: 'invalid',
      message: 'The callback contains conflicting credential fields.',
      sanitizedUrl
    };
  }
  const missing = [
    fields.identity?.status === 'missing' ? fields.identityLabel : null,
    fields.credential.status === 'missing' ? 'credential' : null
  ].filter((value): value is string => Boolean(value));
  if (missing.length > 0) {
    return {
      status: 'incomplete',
      kind,
      missing,
      message: 'The callback link is incomplete.',
      sanitizedUrl
    };
  }
  if (fields.credential.status !== 'ready') {
    return {
      status: 'invalid',
      message: 'The callback credential is invalid.',
      sanitizedUrl
    };
  }

  const credentialRef = options.credentialVault.put(fields.credential.value);
  const base = { databaseId: callbackDatabaseId, credentialRef } as const;
  switch (kind) {
    case 'password-reset':
      return {
        status: 'ready',
        callback: {
          ...base,
          kind,
          roleId: fields.identity?.status === 'ready' ? fields.identity.value : ''
        },
        sanitizedUrl
      };
    case 'email-verification':
      return {
        status: 'ready',
        callback: {
          ...base,
          kind,
          emailId: fields.identity?.status === 'ready' ? fields.identity.value : ''
        },
        sanitizedUrl
      };
    case 'account-deletion':
      return {
        status: 'ready',
        callback: {
          ...base,
          kind,
          userId: fields.identity?.status === 'ready' ? fields.identity.value : ''
        },
        sanitizedUrl
      };
    case 'app-invite':
    case 'organization-invite':
      return {
        status: 'ready',
        callback: { ...base, kind },
        sanitizedUrl
      };
  }
}

export function scrubConstructiveConsoleCallbackLocation(
  result: ConstructiveConsoleCallbackResult,
  location: Pick<Location, 'pathname' | 'search' | 'hash'>,
  history: Pick<History, 'replaceState' | 'state'>
): void {
  if (!result.sanitizedUrl) return;
  const current = `${location.pathname}${location.search}${location.hash}`;
  if (result.sanitizedUrl === current) return;
  history.replaceState(history.state, '', result.sanitizedUrl);
}

'use client';

import * as React from 'react';
import { CircleAlertIcon } from 'lucide-react';

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';

import {
  createDatabaseScopedStandaloneSession,
  createFetchConsoleTransport,
  createConsoleIdentityKey,
  getConsoleSessionIdentity,
  resolveConsoleEndpoint,
  type ConsoleSession,
  type ConsoleEndpoint,
  type ConsoleEndpointMap,
  type ConsoleCsrfTokenProvider,
  type ConsoleRuntimeError,
  type ConsoleTransport,
  type DatabaseScopedStandaloneConsoleSession
} from '../../console-runtime';
import type { FeaturePackId } from '../../../feature-packs';
import { ConsoleKit } from '../console-kit';
import type { ConsoleKitFeatureModule } from '../feature-module';
import type {
  ConsoleKitAdapterEnhancers,
  ConsoleKitAdapters,
  ConsoleKitAuthMethodConfig,
  ConsoleKitConfig,
  ConsoleKitRouteConfig
} from '../console-kit-contracts';
import {
  createConsoleKitStore,
  type ConsoleKitStoreApi
} from '../store';
import { createConstructiveCapabilityDiscovery } from './constructive-capabilities';
import {
  createConstructiveCallbackCredentialVault,
  parseConstructiveConsoleCallback,
  scrubConstructiveConsoleCallbackLocation,
  type ConstructiveCallbackCredentialVault,
  type ConstructiveConsoleCallback,
  type ConstructiveConsoleCallbackResult,
  type ConstructiveConsoleCallbackSource
} from './constructive-callback';

export type ConstructiveTenantDatabase = Readonly<{
  id: string;
  name?: string;
  endpoints: ConsoleEndpointMap;
}>;

/** Host-owned Console Kit session explicitly scoped to one tenant database. */
export type ConstructiveTenantConsoleSession = ConsoleSession & Readonly<{
  databaseId: string;
}>;

export type ConstructiveConsoleKitCoreProps = Readonly<{
  database: ConstructiveTenantDatabase;
  featureModules: readonly ConsoleKitFeatureModule[];
  className?: string;
  order?: readonly FeaturePackId[];
  routes?: ConsoleKitRouteConfig;
  showUnavailable?: boolean;
  /** Expose connection/endpoint diagnostics in the shell (default false). */
  showDiagnostics?: boolean;
  brand?: ConsoleKitConfig['brand'];
  /**
   * Host-owned session for an existing database identity. This is required for
   * data-only tenants because Console Kit cannot mint authority without an auth
   * endpoint, and its databaseId must match the tenant descriptor.
   */
  session?: ConstructiveTenantConsoleSession;
  /** Required when the tenant enables require_csrf_for_auth. */
  csrfTokenProvider?: ConsoleCsrfTokenProvider;
  store?: ConsoleKitStoreApi;
  transport?: ConsoleTransport;
  /**
   * A callback URL/parameter source. Omit it to inspect the current browser
   * location, or pass false when the host owns callback handling.
   */
  callback?: ConstructiveConsoleCallbackSource | false;
  adapterEnhancers?: ConsoleKitAdapterEnhancers;
  authMethods?: ConsoleKitAuthMethodConfig;
  authPasswordPolicy?: ConsoleKitConfig['authPasswordPolicy'];
  featureOptions?: ConsoleKitConfig['featureOptions'];
  onError?: ConsoleKitConfig['onError'];
}>;

export type CreateConstructiveAdaptersOptions = Readonly<{
  store: ConsoleKitStoreApi;
  featureModules: readonly ConsoleKitFeatureModule[];
  session?: DatabaseScopedStandaloneConsoleSession;
  callback?: ConstructiveConsoleCallback;
  callbackCredentials: ConstructiveCallbackCredentialVault;
  authMethods?: ConsoleKitAuthMethodConfig;
  authPasswordPolicy?: ConsoleKitConfig['authPasswordPolicy'];
}>;

function endpoint(
  endpoints: ConsoleEndpointMap,
  kind: ConsoleEndpoint['kind']
): ConsoleEndpoint | null {
  const resolution = resolveConsoleEndpoint(endpoints, kind);
  return resolution.status === 'resolved' ? resolution.endpoint : null;
}

/** Creates the first-party adapters backed by Constructive GraphQL contracts. */
export function createConstructiveConsoleAdapters(
  options: CreateConstructiveAdaptersOptions
): ConsoleKitAdapters {
  const discovery = createConstructiveCapabilityDiscovery(
    options.store,
    options.featureModules
  );
  return Object.fromEntries(options.featureModules.flatMap((module) => {
    // Auth owns the full callback lifecycle, including invitations that must
    // survive an anonymous-to-authenticated identity transition before they
    // can be redeemed. Other packs receive neither the descriptor nor its
    // opaque credential reference.
    const callback = options.callback && module.id === 'auth'
      ? options.callback
      : undefined;
    const adapter = module.createAdapter?.({
      store: options.store,
      discovery,
      session: options.session,
      callback,
      callbackCredentials: options.callbackCredentials,
      authMethods: options.authMethods,
      passwordPolicy: options.authPasswordPolicy
    });
    return adapter
      ? [[module.id, {
          ...adapter,
          requiresCapabilityDiscovery: true
        }] as const]
      : [];
  })) as ConsoleKitAdapters;
}

function isDatabaseScopedStandaloneSession(
  session: ConstructiveTenantConsoleSession | null | undefined
): session is DatabaseScopedStandaloneConsoleSession {
  if (!session || session.mode !== 'standalone') return false;
  const candidate = session as Partial<DatabaseScopedStandaloneConsoleSession>;
  return typeof candidate.signIn === 'function' &&
    typeof candidate.signUp === 'function' &&
    typeof candidate.restorePersistedSession === 'function' &&
    typeof candidate.handleAuthenticationFailure === 'function';
}

function ConfigurationError({ message }: Readonly<{ message: string }>) {
  return (
    <Alert className='m-6 max-w-2xl' variant='destructive'>
      <CircleAlertIcon aria-hidden='true' />
      <AlertTitle>Console Kit is not configured</AlertTitle>
      <AlertDescription>{message}</AlertDescription>
    </Alert>
  );
}

function reportConsoleKitError(error: ConsoleRuntimeError) {
  if (process.env.NODE_ENV !== 'production') {
    console.error('[Constructive Console Kit]', error.message);
  }
}

type CallbackBoundaryState =
  | Readonly<{ status: 'checking' }>
  | ConstructiveConsoleCallbackResult;
const useCallbackBoundaryEffect = typeof window === 'undefined'
  ? React.useEffect
  : React.useLayoutEffect;

function callbackSourceKey(
  source: ConstructiveConsoleCallbackSource | false | undefined
): string {
  if (source === false) return 'disabled';
  if (source === undefined) return 'browser-location';
  if (source instanceof URLSearchParams) {
    return `parameters:${source.toString()}`;
  }
  if (source instanceof URL) return `url:${source.href}`;
  try {
    return `url:${new URL(source, 'https://constructive.invalid').href}`;
  } catch {
    return `string:${source}`;
  }
}

function useConstructiveCallbackBoundary(
  databaseId: string,
  source: ConstructiveConsoleCallbackSource | false | undefined
): Readonly<{
  state: CallbackBoundaryState;
  credentials: ConstructiveCallbackCredentialVault;
}> {
  const credentialsRef = React.useRef<ConstructiveCallbackCredentialVault | null>(null);
  if (!credentialsRef.current) {
    credentialsRef.current = createConstructiveCallbackCredentialVault();
  }
  const credentials = credentialsRef.current;
  const sourceKey = callbackSourceKey(source);
  const captureRef = React.useRef<Readonly<{
    databaseId: string;
    sourceKey: string;
    state: ConstructiveConsoleCallbackResult;
  }> | null>(null);
  const effectGenerationRef = React.useRef(0);
  const [state, setState] = React.useState<CallbackBoundaryState>(
    source === undefined || source === false
      ? { status: 'none' }
      : { status: 'checking' }
  );

  useCallbackBoundaryEffect(() => {
    effectGenerationRef.current += 1;
    const generation = effectGenerationRef.current;
    const releaseAfterEffect = () => {
      queueMicrotask(() => {
        if (effectGenerationRef.current === generation) credentials.clear();
      });
    };
    const captured = captureRef.current;
    if (
      captured?.databaseId === databaseId &&
      captured.sourceKey === sourceKey
    ) {
      setState(captured.state);
      return releaseAfterEffect;
    }

    credentials.clear();
    if (source === false) {
      const result = { status: 'none' } as const;
      captureRef.current = { databaseId, sourceKey, state: result };
      setState(result);
      return releaseAfterEffect;
    }
    if (source === undefined && typeof window === 'undefined') {
      const result = { status: 'none' } as const;
      captureRef.current = { databaseId, sourceKey, state: result };
      setState(result);
      return releaseAfterEffect;
    }

    const selectedSource = source ?? window.location.href;
    const result = parseConstructiveConsoleCallback(selectedSource, {
      databaseId,
      credentialVault: credentials
    });
    if (source === undefined && typeof window !== 'undefined') {
      scrubConstructiveConsoleCallbackLocation(
        result,
        window.location,
        window.history
      );
    }
    captureRef.current = { databaseId, sourceKey, state: result };
    setState(result);
    return releaseAfterEffect;
  }, [credentials, databaseId, source, sourceKey]);

  return { state, credentials };
}

function ConstructiveConsoleKitInstance(props: ConstructiveConsoleKitCoreProps) {
  const callbackBoundary = useConstructiveCallbackBoundary(
    props.database.id,
    props.callback
  );
  const authEndpoint = endpoint(props.database.endpoints, 'auth');
  const externalAuthSession = isDatabaseScopedStandaloneSession(props.session)
    ? props.session
    : null;
  const csrfTokenProviderRef = React.useRef(props.csrfTokenProvider);
  React.useEffect(() => {
    csrfTokenProviderRef.current = props.csrfTokenProvider;
  }, [props.csrfTokenProvider]);
  const resolveCsrfTokenProvider = React.useCallback(
    () => csrfTokenProviderRef.current,
    []
  );
  const internalStoreRef = React.useRef<ConsoleKitStoreApi | null>(null);
  if (!props.store && !internalStoreRef.current) {
    const installed = new Set(props.featureModules.map((module) => module.id));
    const ordered = [...new Set(
      props.order ?? props.featureModules.map((module) => module.id)
    )].filter((feature) => installed.has(feature));
    const startsWithAuth = ordered.includes('auth') && Boolean(authEndpoint) &&
      (!props.session || Boolean(externalAuthSession));
    const preferredRoute = props.routes?.defaultRoute;
    const initialRoute = preferredRoute && ordered.includes(preferredRoute.feature)
      ? preferredRoute
      : startsWithAuth
        ? 'auth'
        : ordered[0] ?? 'data';
    internalStoreRef.current = createConsoleKitStore(
      initialRoute,
      {
        databaseId: props.database.id,
        organizationId: null
      },
      props.featureModules.flatMap((module) =>
        module.storeSlice ? [module.storeSlice] : []
      )
    );
  }
  const store = props.store ?? internalStoreRef.current;
  useCallbackBoundaryEffect(() => {
    if (!store || callbackBoundary.state.status !== 'ready') return;
    const kind = callbackBoundary.state.callback.kind;
    if (
      kind === 'password-reset' ||
      kind === 'email-verification' ||
      kind === 'account-deletion'
    ) {
      store.getState().setAuthFlow({ status: 'callback', kind, phase: 'ready' });
    }
  }, [callbackBoundary.state, store]);

  const hasExternalSession = Boolean(props.session);
  const internalSessionState = React.useMemo<Readonly<{
    session: DatabaseScopedStandaloneConsoleSession | null;
    error: string | null;
  }>>(() => {
    if (hasExternalSession || !authEndpoint) {
      return { session: null, error: null };
    }
    try {
      return {
        session: createDatabaseScopedStandaloneSession({
          databaseId: props.database.id,
          authEndpoint,
          resolveCsrfTokenProvider,
          deferRestore: true
        }),
        error: null
      };
    } catch (cause) {
      return {
        session: null,
        error: cause instanceof Error
          ? cause.message
          : 'The auth endpoint configuration is invalid.'
      };
    }
  }, [
    authEndpoint?.id,
    authEndpoint?.url,
    props.database.id,
    hasExternalSession,
    resolveCsrfTokenProvider
  ]);
  const internalSession = internalSessionState.session;
  const sessionDatabaseMismatch = props.session &&
    props.session.databaseId !== props.database.id;
  const session = sessionDatabaseMismatch
    ? null
    : props.session ?? internalSession;
  const authSession = sessionDatabaseMismatch
    ? null
    : internalSession ?? externalAuthSession;
  React.useEffect(() => {
    if (!session || callbackBoundary.state.status !== 'ready') return;
    const callback = callbackBoundary.state.callback;
    let previous = getConsoleSessionIdentity(session.getSnapshot());
    return session.subscribe(() => {
      const next = getConsoleSessionIdentity(session.getSnapshot());
      const previousKey = previous ? createConsoleIdentityKey(previous) : null;
      const nextKey = next ? createConsoleIdentityKey(next) : null;
      if (previousKey === nextKey) return;

      const preserveInviteThroughAuthentication =
        previous?.kind === 'anonymous' &&
        next?.kind === 'authenticated' &&
        (callback.kind === 'app-invite' ||
          callback.kind === 'organization-invite');
      if (!preserveInviteThroughAuthentication) {
        callbackBoundary.credentials.clear(callback.credentialRef);
      }
      previous = next;
    });
  }, [callbackBoundary.credentials, callbackBoundary.state, session]);
  React.useEffect(() => {
    internalSession?.resume?.();
    authSession?.restorePersistedSession();
    return () => internalSession?.dispose?.();
  }, [authSession, internalSession]);

  const transport = React.useMemo(() => {
    if (props.transport) return props.transport;
    if (!session) return null;
    return createFetchConsoleTransport(fetch, {
      onAuthenticationError: ({ error, identity }) => {
        const code = typeof error.extensions?.code === 'string'
          ? error.extensions.code
          : 'UNAUTHENTICATED';
        authSession?.handleAuthenticationFailure({ message: error.message, code, identity });
      }
    });
  }, [authSession, props.transport, session]);

  const adapters = React.useMemo(() => {
    if (
      !store ||
      !session ||
      callbackBoundary.state.status === 'checking' ||
      callbackBoundary.state.status === 'invalid' ||
      callbackBoundary.state.status === 'incomplete' ||
      callbackBoundary.state.status === 'cross-tenant'
    ) return null;
    return createConstructiveConsoleAdapters({
      store,
      featureModules: props.featureModules,
      session: authEndpoint ? authSession ?? undefined : undefined,
      callback: callbackBoundary.state.status === 'ready'
        ? callbackBoundary.state.callback
        : undefined,
      callbackCredentials: callbackBoundary.credentials,
      authMethods: props.authMethods,
      authPasswordPolicy: props.authPasswordPolicy
    });
  }, [
    callbackBoundary.credentials,
    callbackBoundary.state,
    props.authMethods,
    props.authPasswordPolicy,
    props.featureModules,
    authEndpoint?.id,
    authEndpoint?.url,
    authSession,
    session,
    store
  ]);

  if (callbackBoundary.state.status === 'checking') return null;
  if (
    callbackBoundary.state.status === 'invalid' ||
    callbackBoundary.state.status === 'incomplete' ||
    callbackBoundary.state.status === 'cross-tenant'
  ) {
    return <ConfigurationError message={callbackBoundary.state.message} />;
  }

  if (sessionDatabaseMismatch) {
    return (
      <ConfigurationError
        message='The host-owned session belongs to a different tenant database.'
      />
    );
  }

  if (!store || !session || !transport || !adapters) {
    return (
      <ConfigurationError
        message={internalSessionState.error ??
          'A routable auth endpoint or a matching host-owned session is required for Console Kit.'}
      />
    );
  }

  const reportError = props.onError ?? reportConsoleKitError;
  return (
    <ConsoleKit
      className={props.className}
      featureModules={props.featureModules}
      config={{
        databaseId: props.database.id,
        endpoints: props.database.endpoints,
        session,
        transport,
        adapters,
        adapterEnhancers: props.adapterEnhancers,
        authMethods: props.authMethods,
        authPasswordPolicy: props.authPasswordPolicy,
        order: props.order,
        routes: props.routes,
        showUnavailable: props.showUnavailable ?? true,
        showDiagnostics: props.showDiagnostics,
        featureOptions: props.featureOptions,
        brand: props.brand ?? {
          name: props.database.name?.trim() || 'Application'
        },
        onError: reportError
      }}
      store={store}
    />
  );
}

/**
 * Batteries-included application console for one compatible Constructive
 * tenant database. A database switch remounts every session and cache scope.
 */
export function ConstructiveConsoleKitCore(props: ConstructiveConsoleKitCoreProps) {
  const authEndpoint = endpoint(props.database.endpoints, 'auth');
  const instanceKey = [
    props.database.id,
    authEndpoint?.id ?? 'missing-auth-id',
    authEndpoint?.url ?? 'missing-auth-url',
    props.featureModules.map((module) => module.id).join(',')
  ].join(':');
  return <ConstructiveConsoleKitInstance key={instanceKey} {...props} />;
}

import type { ConsoleEndpointKind } from '../../console-runtime';
import type { ConsoleKitAdapterContext } from '../console-kit-contracts';

export type ConstructiveTypeRef = Readonly<{
  kind: string;
  name?: string | null;
  ofType?: ConstructiveTypeRef | null;
}>;

export type ConstructiveSchemaInput = Readonly<{
  name: string;
  type: ConstructiveTypeRef;
}>;

export type ConstructiveSchemaField = Readonly<{
  name: string;
  args: readonly ConstructiveSchemaInput[];
  type: ConstructiveTypeRef;
}>;

export type ConstructiveSchemaType = Readonly<{
  kind: string;
  name: string;
  fields: readonly ConstructiveSchemaField[];
  inputFields: readonly ConstructiveSchemaInput[];
}>;

export type ConstructiveSchemaSnapshot = Readonly<{
  endpointKind: ConsoleEndpointKind;
  endpointId: string;
  queryFields: Readonly<Record<string, ConstructiveSchemaField>>;
  mutationFields: Readonly<Record<string, ConstructiveSchemaField>>;
  types: Readonly<Record<string, ConstructiveSchemaType>>;
}>;

export type ConstructiveConnectionQuery = Readonly<{
  operationName: string;
  fieldName: string;
  nodeSelection: string;
  pageSize?: number;
}>;

type IntrospectionField = {
  name?: unknown;
  args?: unknown;
  type?: unknown;
};

type IntrospectionType = {
  kind?: unknown;
  name?: unknown;
  fields?: unknown;
  inputFields?: unknown;
};

const CONSTRUCTIVE_SCHEMA_QUERY = `
  query ConsoleKitConstructiveSchema {
    __schema {
      queryType {
        fields {
          name
          args { name type { ...ConsoleKitTypeRef } }
          type { ...ConsoleKitTypeRef }
        }
      }
      mutationType {
        fields {
          name
          args { name type { ...ConsoleKitTypeRef } }
          type { ...ConsoleKitTypeRef }
        }
      }
      types {
        kind
        name
        fields {
          name
          args { name type { ...ConsoleKitTypeRef } }
          type { ...ConsoleKitTypeRef }
        }
        inputFields { name type { ...ConsoleKitTypeRef } }
      }
    }
  }

  fragment ConsoleKitTypeRef on __Type {
    kind
    name
    ofType {
      kind
      name
      ofType {
        kind
        name
        ofType { kind name }
      }
    }
  }
`;

function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object'
    ? value as Record<string, unknown>
    : null;
}

function typeRef(value: unknown): ConstructiveTypeRef {
  const record = asRecord(value);
  return {
    kind: typeof record?.kind === 'string' ? record.kind : 'UNKNOWN',
    name: typeof record?.name === 'string' ? record.name : null,
    ofType: record?.ofType ? typeRef(record.ofType) : null
  };
}

function schemaInputs(value: unknown): ConstructiveSchemaInput[] {
  if (!Array.isArray(value)) return [];
  return value.flatMap((candidate) => {
    const record = asRecord(candidate);
    if (!record || typeof record.name !== 'string') return [];
    return [{ name: record.name, type: typeRef(record.type) }];
  });
}

function schemaFields(value: unknown): ConstructiveSchemaField[] {
  if (!Array.isArray(value)) return [];
  return value.flatMap((candidate) => {
    const field = candidate as IntrospectionField;
    if (typeof field?.name !== 'string') return [];
    return [{
      name: field.name,
      args: schemaInputs(field.args),
      type: typeRef(field.type)
    }];
  });
}

function fieldRecord(fields: readonly ConstructiveSchemaField[]): Record<string, ConstructiveSchemaField> {
  return Object.fromEntries(fields.map((field) => [field.name, field]));
}

function schemaTypes(value: unknown): Record<string, ConstructiveSchemaType> {
  if (!Array.isArray(value)) return {};
  return Object.fromEntries(value.flatMap((candidate) => {
    const type = candidate as IntrospectionType;
    if (typeof type?.name !== 'string' || typeof type.kind !== 'string') return [];
    return [[type.name, {
      kind: type.kind,
      name: type.name,
      fields: schemaFields(type.fields),
      inputFields: schemaInputs(type.inputFields)
    } satisfies ConstructiveSchemaType]];
  }));
}

function rootFields(
  schema: Record<string, unknown>,
  rootKey: 'queryType' | 'mutationType',
  types: Readonly<Record<string, ConstructiveSchemaType>>
): ConstructiveSchemaField[] {
  const root = asRecord(schema[rootKey]);
  const directFields = schemaFields(root?.fields);
  if (directFields.length > 0) return directFields;
  const rootName = typeof root?.name === 'string' ? root.name : null;
  return rootName ? [...(types[rootName]?.fields ?? [])] : [];
}

/**
 * Normalizes either the standard GraphQL introspection response retained by
 * Console Kit metadata or the smaller discovery query used by older hosts.
 */
export function constructiveSchemaSnapshotFromIntrospection(
  endpointKind: ConsoleEndpointKind,
  endpointId: string,
  introspection: unknown
): ConstructiveSchemaSnapshot {
  const payload = asRecord(introspection);
  const schema = asRecord(payload?.__schema);
  if (!schema) {
    throw new Error(
      `The ${endpointKind} endpoint did not return GraphQL schema introspection.`
    );
  }

  const types = schemaTypes(schema.types);
  return {
    endpointKind,
    endpointId,
    queryFields: fieldRecord(rootFields(schema, 'queryType', types)),
    mutationFields: fieldRecord(rootFields(schema, 'mutationType', types)),
    types
  };
}

export function namedTypeName(type: ConstructiveTypeRef | undefined): string | null {
  let current = type;
  while (current) {
    if (current.name) return current.name;
    current = current.ofType ?? undefined;
  }
  return null;
}

export function hasSchemaFields(
  schema: ConstructiveSchemaSnapshot | undefined,
  operation: 'query' | 'mutation',
  fields: readonly string[]
): boolean {
  const available = operation === 'query' ? schema?.queryFields : schema?.mutationFields;
  return fields.every((field) => Boolean(available?.[field]));
}

export function fieldsForType(
  schema: ConstructiveSchemaSnapshot,
  typeName: string
): Readonly<Record<string, ConstructiveSchemaField>> {
  return fieldRecord(schema.types[typeName]?.fields ?? []);
}

export async function executeConstructiveGraphQL<T>(
  runtime: ConsoleKitAdapterContext,
  endpointKind: ConsoleEndpointKind,
  document: string,
  variables: Record<string, unknown> | undefined,
  signal?: AbortSignal
): Promise<T> {
  const transport = runtime.transportFor(endpointKind);
  if (!transport) {
    const error = new Error(`The ${endpointKind} endpoint is not configured.`) as Error & { code?: string };
    error.code = 'ENDPOINT_UNAVAILABLE';
    throw error;
  }

  const result = await transport.execute<T>({ document, variables, signal });
  if (result.ok) return result.data;

  const first = result.errors[0];
  const error = new Error(first?.message || 'The GraphQL operation failed.') as Error & {
    code?: string;
    errors?: typeof result.errors;
  };
  const code = first?.extensions?.code;
  if (typeof code === 'string') error.code = code;
  error.errors = result.errors;
  throw error;
}

/**
 * Reads a PostGraphile Relay connection to exhaustion. Every connection owns
 * its cursor because unrelated tables can advance at different rates.
 */
export async function executeConstructiveConnectionQuery(
  runtime: ConsoleKitAdapterContext,
  endpointKind: ConsoleEndpointKind,
  query: ConstructiveConnectionQuery,
  signal?: AbortSignal
): Promise<Record<string, unknown>[]> {
  const document = `
    query ${query.operationName}($first: Int!, $after: Cursor) {
      ${query.fieldName}(first: $first, after: $after) {
        nodes { ${query.nodeSelection} }
        pageInfo { hasNextPage endCursor }
      }
    }
  `;
  const nodes: Record<string, unknown>[] = [];
  const seenCursors = new Set<string>();
  let after: string | null = null;

  for (;;) {
    const result = await executeConstructiveGraphQL<Record<string, unknown>>(
      runtime,
      endpointKind,
      document,
      { first: query.pageSize ?? 100, after },
      signal
    );
    const connection = asRecord(result[query.fieldName]);
    const pageNodes = Array.isArray(connection?.nodes) ? connection.nodes : [];
    for (const candidate of pageNodes) {
      const node = asRecord(candidate);
      if (node) nodes.push(node);
    }

    const pageInfo = asRecord(connection?.pageInfo);
    if (pageInfo?.hasNextPage !== true) return nodes;
    const endCursor = typeof pageInfo.endCursor === 'string' && pageInfo.endCursor.length > 0
      ? pageInfo.endCursor
      : null;
    if (!endCursor || seenCursors.has(endCursor)) {
      throw new Error(
        `The ${query.fieldName} connection reported another page without a new cursor.`
      );
    }
    seenCursors.add(endCursor);
    after = endCursor;
  }
}

export async function inspectConstructiveSchema(
  runtime: ConsoleKitAdapterContext,
  endpointKind: ConsoleEndpointKind,
  signal?: AbortSignal
): Promise<ConstructiveSchemaSnapshot> {
  const endpoint = runtime.endpoints[endpointKind];
  if (!endpoint) {
    throw new Error(`The ${endpointKind} endpoint is not configured.`);
  }
  const data = await executeConstructiveGraphQL<{
    __schema?: {
      queryType?: { fields?: unknown } | null;
      mutationType?: { fields?: unknown } | null;
      types?: unknown;
    } | null;
  }>(runtime, endpointKind, CONSTRUCTIVE_SCHEMA_QUERY, undefined, signal);
  return constructiveSchemaSnapshotFromIntrospection(
    endpointKind,
    endpoint.id,
    data
  );
}

export function selectExistingFields(
  schema: ConstructiveSchemaSnapshot,
  typeName: string,
  desired: readonly string[]
): string[] {
  const fields = fieldsForType(schema, typeName);
  return desired.filter((field) => Boolean(fields[field]));
}

import type { MetaschemaField, MetaschemaTable } from '@constructive-io/data';

import type { ConsoleKitMetadataState } from '../console-kit-contracts';

const GRAPHQL_NAME = /^[_A-Za-z][_0-9A-Za-z]*$/u;

export type ConstructiveMetaTableContract = Readonly<{
  table: MetaschemaTable;
  root: string;
}>;

export function isConstructiveGraphQLName(value: string): boolean {
  return GRAPHQL_NAME.test(value);
}

export function canonicalMetaName(
  value: string | null | undefined
): string {
  return (value ?? '').replace(/[^A-Za-z0-9]/gu, '').toLowerCase();
}

export function compatibleMetaTables(
  metadata: ConsoleKitMetadataState
): MetaschemaTable[] {
  if (metadata.status !== 'compatible') return [];
  return (metadata.meta._meta?.tables ?? []).filter(
    (table): table is MetaschemaTable => Boolean(table)
  );
}

export function readableMetaTable(
  table: MetaschemaTable
): ConstructiveMetaTableContract | null {
  const root = table.query?.all;
  if (!root || !isConstructiveGraphQLName(root)) return null;
  return { table, root };
}

export function metaFields(table: MetaschemaTable): MetaschemaField[] {
  return (table.fields ?? []).filter(
    (field): field is MetaschemaField =>
      field != null && isConstructiveGraphQLName(field.name)
  );
}

export function metaFieldName(
  table: MetaschemaTable,
  aliases: readonly string[]
): string | undefined {
  const candidates = metaFields(table);
  for (const alias of aliases) {
    const match = candidates.find(
      (field) => canonicalMetaName(field.name) === alias
    );
    if (match) return match.name;
  }
  return undefined;
}

export function metaPrimaryKeyField(
  table: MetaschemaTable
): string | undefined {
  const constraints = table.constraints;
  const hasConstraintMetadata = constraints !== undefined && constraints !== null;
  if (constraints && !Array.isArray(constraints)) {
    const current = constraints.primaryKey;
    if (!current) return undefined;
    const fields = (current.fields ?? []).filter(
      (field): field is MetaschemaField =>
        field != null && isConstructiveGraphQLName(field.name)
    );
    return fields.length === 1 ? fields[0]?.name : undefined;
  }

  if (Array.isArray(constraints)) {
    const current = constraints.filter(
      (constraint) => constraint?.__typename === 'MetaPrimaryKeyConstraint'
    );
    if (current.length !== 1) return undefined;
    const fields = (current[0]?.fields ?? []).filter(
      (field): field is MetaschemaField =>
        field != null && isConstructiveGraphQLName(field.name)
    );
    return fields.length === 1 ? fields[0]?.name : undefined;
  }

  const hasLegacyMetadata = table.primaryKeyConstraints !== undefined &&
    table.primaryKeyConstraints !== null;
  const legacy = (table.primaryKeyConstraints ?? []).filter(
    (constraint): constraint is NonNullable<typeof constraint> =>
      constraint != null
  );
  if (legacy.length > 0) {
    if (legacy.length !== 1) return undefined;
    const fields = (legacy[0]?.fields ?? []).filter(
      (field): field is MetaschemaField =>
        field != null && isConstructiveGraphQLName(field.name)
    );
    return fields.length === 1 ? fields[0]?.name : undefined;
  }

  // The id fallback exists only for cached metadata predating PK fields. An
  // explicit no-PK or composite-PK declaration must never be collapsed to id.
  return hasConstraintMetadata || hasLegacyMetadata
    ? undefined
    : metaFieldName(table, ['id']);
}

export function metaTableNames(table: MetaschemaTable): string[] {
  return [
    table.name,
    table.inflection?.tableType,
    table.inflection?.allRows
  ].flatMap((value) => {
    const canonical = canonicalMetaName(value);
    if (!canonical) return [];
    return canonical.endsWith('s')
      ? [canonical, canonical.slice(0, -1)]
      : [canonical];
  });
}

export function metaTableNamespace(table: MetaschemaTable): string {
  return [table.schemaName, table.name].filter(Boolean).join('.') || table.name;
}

export function metaSelection(
  fields: readonly (string | undefined)[]
): string {
  return [...new Set(
    fields.filter((field): field is string => Boolean(field))
  )].join(' ');
}

