> = (set) => ({
  session: { status: 'loading' },
  setSession: (session) => set((state) => {
    if (identityScope(state.session) === identityScope(session)) {
      return { session };
    }
    return {
      session,
      context: state.context
        ? { ...state.context, organizationId: null }
        : null
    };
  })
});

